import json
import hashlib
import os
import sqlite3
from flask import Flask, request, jsonify
from functools import lru_cache
import re
import bleach

app = Flask(__name__)
DB_PATH = '/var/app/data/widgets.db'

# Security utilities
def sanitize_html(text):
    return bleach.clean(text, tags=[], strip=True)

def validate_username(username):
    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        raise ValueError("Invalid username")
    return username

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

# Widget configuration system
class ConfigRegistry:
    """Manages widget configuration templates and user overrides."""

    _MAX_CACHE_ENTRIES = 1024

    _default_configs = {
        'dashboard': {'layout': 'grid', 'refresh': 30, 'theme': 'light'},
        'analytics': {'period': '7d', 'charts': ['line', 'bar']},
        'notifications': {'email': True, 'push': False, 'digest': 'daily'}
    }

    # Allowed value types per config key for strict validation
    _type_constraints = {
        'layout': str, 'refresh': int, 'theme': str,
        'period': str, 'charts': list,
        'email': bool, 'push': bool, 'digest': str
    }

    _allowed_values = {
        'layout': ['grid', 'list', 'compact'],
        'theme': ['light', 'dark', 'auto'],
        'digest': ['daily', 'weekly', 'never'],
        'period': ['1d', '7d', '30d', '90d']
    }

    def __init__(self):
        self._cache = {}

    def get_default(self, widget_type):
        return self._default_configs.get(widget_type, {}).copy()

    def _compute_cache_key(self, username, widget_type):
        raw = f"{username}:{widget_type}"
        return hashlib.sha256(raw.encode()).hexdigest()[:16]

    def invalidate(self, username, widget_type):
        """Invalidate a cached resolved config after an update."""
        cache_key = self._compute_cache_key(username, widget_type)
        self._cache.pop(cache_key, None)

    def _merge_configs(self, base, override_data):
        """Merge user override into base config.
        override_data is a JSON config string.
        """
        if not override_data:
            return base
        parsed = self._parse_config_data(override_data)
        if not isinstance(parsed, dict):
            return base
        # Only allow known keys from base with type validation
        merged = base.copy()
        for key in base:
            if key in parsed:
                value = parsed[key]
                # Strict type checking
                expected_type = self._type_constraints.get(key)
                if expected_type and not isinstance(value, expected_type):
                    continue
                # Value allowlist for string enums
                if key in self._allowed_values:
                    if value not in self._allowed_values[key]:
                        continue
                # Range check for integers
                if isinstance(value, int) and (value < 0 or value > 3600):
                    continue
                # Length check for lists
                if isinstance(value, list):
                    if len(value) > 10 or not all(isinstance(x, str) and len(x) < 32 for x in value):
                        continue
                merged[key] = value
        return merged

    def _parse_config_data(self, data_str):
        """Parse configuration data from stored JSON format."""
        try:
            return json.loads(data_str)
        except (json.JSONDecodeError, TypeError):
            return {}

    def resolve_config(self, username, widget_type, user_override=None):
        cache_key = self._compute_cache_key(username, widget_type)
        if cache_key in self._cache and user_override is None:
            return self._cache[cache_key]

        base = self.get_default(widget_type)
        if not base:
            return None

        result = self._merge_configs(base, user_override)
        # Bound the cache to prevent unbounded memory growth (DoS).
        if cache_key not in self._cache and len(self._cache) >= self._MAX_CACHE_ENTRIES:
            # Evict an arbitrary existing entry to make room.
            self._cache.pop(next(iter(self._cache)))
        self._cache[cache_key] = result
        return result

registry = ConfigRegistry()

# Data access layer - properly parameterized
def save_widget_config(username, widget_type, config_json):
    db = get_db()
    try:
        db.execute(
            "INSERT OR REPLACE INTO widget_configs (username, widget_type, config_data) VALUES (?, ?, ?)",
            (username, widget_type, config_json)
        )
        db.commit()
    finally:
        db.close()

def load_widget_config(username, widget_type):
    db = get_db()
    try:
        row = db.execute(
            "SELECT config_data FROM widget_configs WHERE username = ? AND widget_type = ?",
            (username, widget_type)
        ).fetchone()
        return row['config_data'] if row else None
    finally:
        db.close()

# Audit logging with parameterized queries
def log_config_change(username, widget_type, action):
    db = get_db()
    try:
        db.execute(
            "INSERT INTO audit_log (username, widget_type, action, timestamp) VALUES (?, ?, ?, datetime('now'))",
            (username, widget_type, action)
        )
        db.commit()
    finally:
        db.close()

# API endpoints
@app.route('/api/widgets/<widget_type>/config', methods=['GET'])
def get_widget_config(widget_type):
    username = validate_username(request.headers.get('X-Username', ''))

    if widget_type not in ConfigRegistry._default_configs:
        return jsonify({'error': 'Unknown widget type'}), 404

    # Load any saved override from DB
    saved_override = load_widget_config(username, widget_type)

    # Resolve final config (merges default + user override)
    config = registry.resolve_config(username, widget_type, saved_override)
    if config is None:
        return jsonify({'error': 'Unknown widget type'}), 404

    return jsonify({'widget': widget_type, 'config': config})

@app.route('/api/widgets/<widget_type>/config', methods=['PUT'])
def update_widget_config(widget_type):
    username = validate_username(request.headers.get('X-Username', ''))

    if widget_type not in ConfigRegistry._default_configs:
        return jsonify({'error': 'Unknown widget type'}), 404

    # User submits their config override as JSON
    config_data = request.get_data(as_text=True)
    if not config_data or len(config_data) > 4096:
        return jsonify({'error': 'Invalid config data'}), 400

    # Validate it parses and resolves correctly before saving
    resolved = registry.resolve_config(username, widget_type, config_data)
    if resolved is None:
        return jsonify({'error': 'Config resolution failed'}), 400

    # Persist the validated JSON override
    save_widget_config(username, widget_type, config_data)
    # Invalidate stale cached resolution so subsequent GETs reflect the update.
    registry.invalidate(username, widget_type)
    log_config_change(username, widget_type, 'update')

    return jsonify({'widget': widget_type, 'config': resolved})

@app.route('/api/widgets/bulk-export', methods=['POST'])
def bulk_export():
    """Export configs for multiple widgets at once."""
    username = validate_username(request.headers.get('X-Username', ''))

    body = request.get_json(silent=True)
    if not body or not isinstance(body, dict):
        return jsonify({'error': 'Invalid request'}), 400

    widget_types = body.get('widgets', [])
    if not isinstance(widget_types, list) or len(widget_types) > 10:
        return jsonify({'error': 'Invalid widget list'}), 400

    results = {}
    for wt in widget_types:
        if not isinstance(wt, str) or wt not in ConfigRegistry._default_configs:
            continue
        saved = load_widget_config(username, wt)
        config = registry.resolve_config(username, wt, saved)
        if config:
            results[wt] = config

    return jsonify({'configs': results})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
